// TestPGSearchContentIncludeChildren verifies that IncludeChildren=true
// surfaces tool_input and tool_result matches from child (subagent) sessions,
// while IncludeChildren=false excludes them. The scoped CTE wraps only the
// sessions table, so id is unambiguous in the tool-table JOINs.
func TestPGSearchContentIncludeChildren(t *testing.T) {
	store := setupContentSearch(t)

	// Parent session (non-child, passes root filter).
	insertCSSession(t, store, "ic-parent", "proj", "claude",
		"2026-05-01T10:00:00Z", "2026-05-01T10:30:00Z")
	insertCSMessage(t, store, "ic-parent", 0, "assistant",
		"parent running tool", "2026-05-01T10:00:00Z", false)

	// Child session linked to the parent.
	insertCSChildSession(t, store, "ic-child", "proj", "claude",
		"ic-parent", "2026-05-01T10:05:00Z", "2026-05-01T10:25:00Z")
	// Message needed so the JOIN in tool branches can resolve the timestamp.
	insertCSMessage(t, store, "ic-child", 0, "assistant",
		"child running tool", "2026-05-01T10:05:00Z", false)
	insertCSToolCall(t, store, "ic-child", 0, 0,
		"Bash", "child-tu1",
		`{"command":"CHILDNEEDLE"}`, "CHILDNEEDLE in result")

	// Also add a tool_result_events row for the child to cover that branch.
	insertCSChildSession(t, store, "ic-child2", "proj", "claude",
		"ic-parent", "2026-05-01T10:10:00Z", "2026-05-01T10:20:00Z")
	insertCSMessage(t, store, "ic-child2", 0, "assistant",
		"child2 running tool", "2026-05-01T10:10:00Z", false)
	insertCSToolCall(t, store, "ic-child2", 0, 0,
		"Bash", "child2-tu1", `{"command":"ls"}`, "")
	insertCSToolResultEvent(t, store, "ic-child2", 0, 0, 0,
		"child2-tu1", "CHILDNEEDLE in event output")

	ctx := context.Background()

	// --- IncludeChildren=true: child tool_input match must be found ---
	withChildren, err := store.SearchContent(ctx, db.ContentSearchFilter{
		Pattern:         "CHILDNEEDLE",
		Mode:            "substring",
		Sources:         []string{"tool_input", "tool_result"},
		Limit:           50,
		IncludeChildren: true,
		IncludeOneShot:  true,
	})
	require.NoError(t, err, "SearchContent IncludeChildren=true")

	var foundToolInput, foundToolResult bool
	for _, m := range withChildren.Matches {
		if m.SessionID == "ic-child" && m.Location == "tool_input" {
			foundToolInput = true
		}
		if m.SessionID == "ic-child2" && m.Location == "tool_result" {
			foundToolResult = true
		}
	}
	assert.True(t, foundToolInput,
		"IncludeChildren=true: child tool_input match not found; matches=%+v",
		withChildren.Matches)
	assert.True(t, foundToolResult,
		"IncludeChildren=true: child tool_result event match not found; matches=%+v",
		withChildren.Matches)

	// --- IncludeChildren=false: child matches must be absent ---
	withoutChildren, err := store.SearchContent(ctx, db.ContentSearchFilter{
		Pattern:         "CHILDNEEDLE",
		Mode:            "substring",
		Sources:         []string{"tool_input", "tool_result"},
		Limit:           50,
		IncludeChildren: false,
		IncludeOneShot:  true,
	})
	require.NoError(t, err, "SearchContent IncludeChildren=false")
	for _, m := range withoutChildren.Matches {
		assert.NotContains(t, []string{"ic-child", "ic-child2"}, m.SessionID,
			"IncludeChildren=false: child session %q appeared in results", m.SessionID)
	}
}

package postgres

import (
	"context"
	"database/sql"
	"database/sql/driver"
	"errors"
	"io"
	"sync"
	"testing"
	"time"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"go.kenn.io/agentsview/internal/config"
	"go.kenn.io/agentsview/internal/db"
)

type pricingProbeDriver struct{}

type pricingProbeConn struct {
	state *pricingProbeState
}

type pricingProbeRows struct {
	columns []string
	values  [][]driver.Value
	next    int
}

type pricingProbeState struct {
	mu               sync.Mutex
	doneOnce         sync.Once
	queries          int
	err              error
	rows             [][]driver.Value
	block            <-chan struct{}
	afterCancelBlock <-chan struct{}
	done             chan struct{}
}

var (
	pricingProbeRegisterOnce sync.Once
	pricingProbeStatesMu     sync.Mutex
	pricingProbeStates       = map[string]*pricingProbeState{}
)

func newPricingProbeDB(
	t *testing.T, state *pricingProbeState,
) *sql.DB {
	t.Helper()
	pricingProbeRegisterOnce.Do(func() {
		sql.Register("agentsview_pricing_probe", pricingProbeDriver{})
	})
	name := t.Name()
	pricingProbeStatesMu.Lock()
	pricingProbeStates[name] = state
	pricingProbeStatesMu.Unlock()
	t.Cleanup(func() {
		pricingProbeStatesMu.Lock()
		delete(pricingProbeStates, name)
		pricingProbeStatesMu.Unlock()
	})

	pg, err := sql.Open("agentsview_pricing_probe", name)
	require.NoError(t, err, "open pricing probe db")
	t.Cleanup(func() { pg.Close() })
	return pg
}

func (pricingProbeDriver) Open(name string) (driver.Conn, error) {
	pricingProbeStatesMu.Lock()
	state := pricingProbeStates[name]
	pricingProbeStatesMu.Unlock()
	return &pricingProbeConn{state: state}, nil
}

func (c *pricingProbeConn) Prepare(string) (driver.Stmt, error) {
	return nil, errors.New("prepare not implemented")
}

func (c *pricingProbeConn) Close() error { return nil }

func (c *pricingProbeConn) Begin() (driver.Tx, error) {
	return nil, errors.New("begin not implemented")
}

func (c *pricingProbeConn) QueryContext(
	ctx context.Context, query string, _ []driver.NamedValue,
) (driver.Rows, error) {
	defer func() {
		if c.state.done != nil {
			c.state.doneOnce.Do(func() { close(c.state.done) })
		}
	}()
	c.state.mu.Lock()
	c.state.queries++
	err := c.state.err
	values := append([][]driver.Value(nil), c.state.rows...)
	block := c.state.block
	afterCancelBlock := c.state.afterCancelBlock
	c.state.mu.Unlock()
	if block != nil {
		select {
		case <-block:
		case <-ctx.Done():
			if afterCancelBlock != nil {
				<-afterCancelBlock
			}
			return nil, ctx.Err()
		}
	}
	if err != nil {
		return nil, err
	}
	return &pricingProbeRows{
		columns: []string{
			"model_pattern",
			"input_per_mtok",
			"output_per_mtok",
			"cache_creation_per_mtok",
			"cache_read_per_mtok",
			"updated_at",
		},
		values: values,
	}, nil
}

func (r *pricingProbeRows) Columns() []string { return r.columns }

func (r *pricingProbeRows) Close() error { return nil }

func (r *pricingProbeRows) Next(dest []driver.Value) error {
	if r.next >= len(r.values) {
		return io.EOF
	}
	copy(dest, r.values[r.next])
	r.next++
	return nil
}

func (s *pricingProbeState) queryCount() int {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.queries
}

func (s *pricingProbeState) setRows(rows [][]driver.Value) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.rows = rows
}

func (s *pricingProbeState) unblockNextQuery() {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.block = nil
	s.afterCancelBlock = nil
}

func TestCustomPricingOverridesPricingMap(t *testing.T) {
	tests := []struct {
		name      string
		dbPrices  []db.ModelPricing
		custom    map[string]config.CustomModelRate
		model     string
		wantInput float64
	}{
		{
			name:      "db pricing only",
			dbPrices:  []db.ModelPricing{{ModelPattern: "acme-ultra-2.1", InputPerMTok: 1.0}},
			model:     "acme-ultra-2.1",
			wantInput: 1.0,
		},
		{
			name:      "custom overrides db",
			dbPrices:  []db.ModelPricing{{ModelPattern: "acme-ultra-2.1", InputPerMTok: 1.0}},
			custom:    map[string]config.CustomModelRate{"acme-ultra-2.1": {Input: 9.0}},
			model:     "acme-ultra-2.1",
			wantInput: 9.0,
		},
		{
			name:      "custom adds new model",
			custom:    map[string]config.CustomModelRate{"new-model": {Input: 4.0}},
			model:     "new-model",
			wantInput: 4.0,
		},
		{
			name:      "custom does not affect other models",
			dbPrices:  []db.ModelPricing{{ModelPattern: "db-model", InputPerMTok: 2.0}},
			custom:    map[string]config.CustomModelRate{"other": {Input: 99.0}},
			model:     "db-model",
			wantInput: 2.0,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			s := &Store{}
			s.SetCustomPricing(tt.custom)
			out := pricingRowsToMap(tt.dbPrices)
			s.applyCustomPricing(out)
			got, ok := out[tt.model]
			require.True(t, ok, "model %q not in map", tt.model)
			assert.InDelta(t, tt.wantInput, got.input, 0.001)
		})
	}
}

func TestLoadPricingMapSharesConcurrentDBRows(t *testing.T) {
	block := make(chan struct{})
	state := &pricingProbeState{
		rows: [][]driver.Value{{
			"db-model", 1.0, 2.0, 3.0, 4.0, "2026-06-08",
		}},
		block: block,
	}
	pg := newPricingProbeDB(t, state)
	store := &Store{pg: pg}

	type result struct {
		prices map[string]modelRates
		err    error
	}
	results := make(chan result, 2)
	go func() {
		prices, err := store.loadPricingMap(context.Background())
		results <- result{prices: prices, err: err}
	}()
	require.Eventually(t, func() bool {
		return state.queryCount() == 1
	}, time.Second, 10*time.Millisecond)

	go func() {
		prices, err := store.loadPricingMap(context.Background())
		results <- result{prices: prices, err: err}
	}()
	require.Never(t, func() bool {
		return state.queryCount() > 1
	}, 50*time.Millisecond, 10*time.Millisecond)
	close(block)

	first := <-results
	second := <-results
	require.NoError(t, first.err, "first loadPricingMap")
	require.NoError(t, second.err, "second loadPricingMap")
	require.Equal(t, 1, state.queryCount(), "pricing queries")
	first.prices["db-model"] = modelRates{input: 99.0}
	assert.InDelta(t, 1.0, second.prices["db-model"].input, 0.001)
}

