package pricing

import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"time"
)

const litellmURL = "https://raw.githubusercontent.com/" +
	"BerriAI/litellm/main/" +
	"model_prices_and_context_window.json"

// ModelPricing holds per-model token pricing in cost per
// million tokens. Separate from db.ModelPricing — the CLI
// command converts between the two.
type ModelPricing struct {
	ModelPattern         string
	InputPerMTok         float64
	OutputPerMTok        float64
	CacheCreationPerMTok float64
	CacheReadPerMTok     float64
}

type litellmEntry struct {
	InputCost         *float64 `json:"input_cost_per_token"`
	OutputCost        *float64 `json:"output_cost_per_token"`
	CacheCreationCost *float64 `json:"cache_creation_input_token_cost"`
	CacheReadCost     *float64 `json:"cache_read_input_token_cost"`
	Provider          string   `json:"litellm_provider"`
}

const perMTok = 1_000_000

// FetchLiteLLMPricing downloads the LiteLLM pricing JSON
// and parses it into ModelPricing entries.
func FetchLiteLLMPricing() ([]ModelPricing, error) {
	client := &http.Client{Timeout: 30 * time.Second}
	resp, err := client.Get(litellmURL)
	if err != nil {
		return nil, fmt.Errorf("fetching litellm pricing: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf(
			"fetching litellm pricing: status %d", resp.StatusCode,
		)
	}

	data, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, fmt.Errorf("reading litellm response: %w", err)
	}

	return ParseLiteLLMPricing(data)
}

// ParseLiteLLMPricing parses the LiteLLM JSON map into
// ModelPricing entries. Per-token costs are converted to
// per-million-token costs. Entries missing both input and
// output cost are skipped.
func ParseLiteLLMPricing(
	data []byte,
) ([]ModelPricing, error) {
	var raw map[string]litellmEntry
	if err := json.Unmarshal(data, &raw); err != nil {
		return nil, fmt.Errorf("parsing litellm JSON: %w", err)
	}

	var prices []ModelPricing
	for model, entry := range raw {
		if entry.InputCost == nil && entry.OutputCost == nil {
			continue
		}
		p := ModelPricing{ModelPattern: model}
		if entry.InputCost != nil {
			p.InputPerMTok = *entry.InputCost * perMTok
		}
		if entry.OutputCost != nil {
			p.OutputPerMTok = *entry.OutputCost * perMTok
		}
		if entry.CacheCreationCost != nil {
			p.CacheCreationPerMTok =
				*entry.CacheCreationCost * perMTok
		}
		if entry.CacheReadCost != nil {
			p.CacheReadPerMTok = *entry.CacheReadCost * perMTok
		}
		prices = append(prices, p)
	}
	return prices, nil
}

// Register @testing-library/svelte's per-test setup/cleanup against the
// explicitly imported vitest hooks. The library's own auto-registration only
// fires when afterEach is a global, which it is not here (globals are off), so
// component tests using render() would otherwise leak mounted DOM between
// cases. cleanup() is idempotent, so tests that unmount manually are unharmed.
import "@testing-library/svelte/vitest";

type StorageName = "localStorage";

function isStorageLike(value: unknown): value is Storage {
  if (value === null || typeof value !== "object") return false;
  const storage = value as Partial<Storage>;
  return (
    typeof storage.clear === "function" &&
    typeof storage.getItem === "function" &&
    typeof storage.key === "function" &&
    typeof storage.removeItem === "function" &&
    typeof storage.setItem === "function"
  );
}

function existingStorage(name: StorageName): Storage | undefined {
  const descriptor = Object.getOwnPropertyDescriptor(globalThis, name);
  if (!descriptor || !("value" in descriptor)) return undefined;
  return isStorageLike(descriptor.value) ? descriptor.value : undefined;
}

export function installFallbackStorage(name: StorageName): void {
  if (existingStorage(name)) return;

  const store = new Map<string, string>();
  const storage: Storage = {
    get length() {
      return store.size;
    },
    clear() {
      store.clear();
    },
    getItem(key: string) {
      return store.get(key) ?? null;
    },
    key(index: number) {
      return [...store.keys()][index] ?? null;
    },
    removeItem(key: string) {
      store.delete(key);
    },
    setItem(key: string, value: string) {
      store.set(key, String(value));
    },
  };

  Object.defineProperty(globalThis, name, {
    value: storage,
    configurable: true,
    writable: true,
  });
}

installFallbackStorage("localStorage");

import { afterEach, describe, expect, it } from "vitest";
import { installFallbackStorage } from "./vitest-setup";

describe("vitest setup storage fallback", () => {
  const originalDescriptor = Object.getOwnPropertyDescriptor(
    globalThis,
    "localStorage",
  );

  afterEach(() => {
    if (originalDescriptor) {
      Object.defineProperty(globalThis, "localStorage", originalDescriptor);
    } else {
      delete (globalThis as { localStorage?: Storage }).localStorage;
    }
  });

  it("installs localStorage when the Node global getter returns undefined", () => {
    Object.defineProperty(globalThis, "localStorage", {
      configurable: true,
      get: () => undefined,
    });

    installFallbackStorage("localStorage");

    localStorage.setItem("agentsview-test-key", "value");

    expect(localStorage.getItem("agentsview-test-key")).toBe("value");
    expect(localStorage.length).toBe(1);
    expect(localStorage.key(0)).toBe("agentsview-test-key");
  });

  it("installs localStorage when the Node global value is not Storage-like", () => {
    Object.defineProperty(globalThis, "localStorage", {
      configurable: true,
      value: {},
    });

    installFallbackStorage("localStorage");

    localStorage.setItem("agentsview-test-key", "value");

    expect(localStorage.getItem("agentsview-test-key")).toBe("value");
  });

  it("does not invoke a non-storage localStorage accessor", () => {
    let reads = 0;
    Object.defineProperty(globalThis, "localStorage", {
      configurable: true,
      get: () => {
        reads += 1;
        return {};
      },
    });

    installFallbackStorage("localStorage");

    localStorage.setItem("agentsview-test-key", "value");

    expect(reads).toBe(0);
    expect(localStorage.getItem("agentsview-test-key")).toBe("value");
  });
});

