package main

import (
	"strings"
	"testing"

	"github.com/stretchr/testify/assert"
)

func TestSanitizeTerminal(t *testing.T) {
	tests := []struct {
		name string
		in   string
		want string
	}{
		{
			name: "plain text",
			in:   "hello world",
			want: "hello world",
		},
		{
			name: "newline and tab preserved; CR stripped",
			in:   "line1\nline2\ttab\rcr",
			want: "line1\nline2\ttabcr",
		},
		{
			// Bare \r on a TTY returns the cursor to column 0
			// and lets later text overwrite earlier output —
			// a spoofing vector even without ANSI escapes.
			name: "strips bare CR to block overwrite attacks",
			in:   "safe output\rEVIL",
			want: "safe outputEVIL",
		},
		{
			// CRLF from Windows-style sources collapses to LF;
			// terminals treat \n alone as a newline so display
			// still looks right.
			name: "CRLF collapses to LF",
			in:   "line1\r\nline2",
			want: "line1\nline2",
		},
		{
			name: "strips ESC (C0)",
			in:   "safe\x1bdangerous",
			want: "safedangerous",
		},
		{
			name: "strips ANSI CSI (cursor up)",
			in:   "before\x1b[1Aoverwritten",
			want: "before[1Aoverwritten",
		},
		{
			// ESC (0x1b) is dropped, so the OSC introducer is
			// broken. The literal "]8;;…" bytes remain but are
			// no longer interpreted as an escape sequence.
			name: "strips OSC 8 hyperlink escape",
			in:   "click \x1b]8;;https://evil.example\x1b\\me\x1b]8;;\x1b\\",
			want: "click ]8;;https://evil.example\\me]8;;\\",
		},
		{
			// BEL (0x07) is a C0 control and also dropped.
			name: "strips OSC 52 clipboard escape",
			in:   "benign \x1b]52;c;ZXZpbA==\x07 end",
			want: "benign ]52;c;ZXZpbA== end",
		},
		{
			name: "strips title-set OSC 2",
			in:   "\x1b]2;rm -rf /\x07after",
			want: "]2;rm -rf /after",
		},
		{
			name: "strips NUL and DEL",
			in:   "a\x00b\x7fc",
			want: "abc",
		},
		{
			name: "strips raw C1 bytes",
			in:   "x\x80y\x9fz",
			want: "xyz",
		},
		{
			name: "preserves multibyte UTF-8",
			in:   "héllo 日本語 😀",
			want: "héllo 日本語 😀",
		},
		{
			name: "empty string",
			in:   "",
			want: "",
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			got := sanitizeTerminal(tc.in)
			assert.Equal(t, tc.want, got,
				"sanitizeTerminal(%q)", tc.in)
			// Post-condition: no ESC byte or NUL in output.
			assert.False(t, strings.ContainsRune(got, 0x1b),
				"output still contains ESC: %q", got)
			assert.False(t, strings.ContainsRune(got, 0),
				"output still contains NUL: %q", got)
		})
	}
}

package server_test

import (
	"net/url"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"go.kenn.io/agentsview/internal/db"
)

func TestHandleSearchSession(t *testing.T) {
	t.Parallel()

	te := setup(t)
	te.seedSession(t, "s1", "proj", 4)
	te.seedMessages(t, "s1", 4, func(i int, m *db.Message) {
		switch i {
		case 0:
			m.Content = "Hello world, this is a test"
		case 1:
			m.Content = "import os; print(os.getcwd())"
		case 2:
			m.Content = "Another message about testing"
		case 3:
			m.Content = "No special content here"
		}
		m.ContentLength = len(m.Content)
	})

	// Second session to verify isolation
	te.seedSession(t, "s2", "proj", 1)
	te.seedMessages(t, "s2", 1, func(_ int, m *db.Message) {
		m.Content = "test content in other session"
		m.ContentLength = len(m.Content)
	})

	type searchResp struct {
		Ordinals []int `json:"ordinals"`
	}

	tests := []struct {
		name         string
		sessionID    string
		query        string
		wantStatus   int
		wantOrdinals []int
	}{
		{
			name:         "matches single message",
			sessionID:    "s1",
			query:        "Hello",
			wantStatus:   200,
			wantOrdinals: []int{0},
		},
		{
			name:         "case insensitive match",
			sessionID:    "s1",
			query:        "IMPORT",
			wantStatus:   200,
			wantOrdinals: []int{1},
		},
		{
			name:         "matches multiple messages",
			sessionID:    "s1",
			query:        "test",
			wantStatus:   200,
			wantOrdinals: []int{0, 2},
		},
		{
			name:         "no match returns empty slice",
			sessionID:    "s1",
			query:        "nonexistent",
			wantStatus:   200,
			wantOrdinals: []int{},
		},
		{
			name:         "scoped to session — does not include s2 results",
			sessionID:    "s1",
			query:        "other session",
			wantStatus:   200,
			wantOrdinals: []int{},
		},
		{
			name:         "empty query returns empty slice",
			sessionID:    "s1",
			query:        "",
			wantStatus:   200,
			wantOrdinals: []int{},
		},
		{
			name:         "results in ordinal order",
			sessionID:    "s1",
			query:        "test",
			wantStatus:   200,
			wantOrdinals: []int{0, 2},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			path := "/api/v1/sessions/" + tt.sessionID + "/search"
			if tt.query != "" {
				path += "?q=" + url.QueryEscape(tt.query)
			}
			w := te.get(t, path)
			assertStatus(t, w, tt.wantStatus)

			resp := decode[searchResp](t, w)
			if resp.Ordinals == nil {
				resp.Ordinals = []int{}
			}
			require.Len(t, resp.Ordinals, len(tt.wantOrdinals), "ordinals = %v", resp.Ordinals)
			for i, ord := range resp.Ordinals {
				assert.Equal(t, tt.wantOrdinals[i], ord, "ordinal[%d]", i)
			}
		})
	}
}

